import React, { useState, useEffect } from 'react';
import { Modal, Button, Form, Spinner, Alert } from 'react-bootstrap';
import * as Sentry from "@sentry/react";

const OAuthTokenExchangeModal = ({ show, onHide, showNotification, sendAdminActionWebhook, adminUserEmail, onUserDataReceived }) => {
    // Determine default token endpoint using environment base or fallback to the French UCP domain.
    const [tokenUrl, setTokenUrl] = useState(() => {
        const base = process.env.REACT_APP_GTAWORLD_OAUTH_BASE_URL || 'https://ucp-fr.gta.world';
        return `${base}/oauth/token`;
    });
    const [clientId, setClientId] = useState(process.env.REACT_APP_GTAWORLD_CLIENT_ID || '');
    const [clientSecret, setClientSecret] = useState('');
    const [redirectUri, setRedirectUri] = useState(() => {
        const isGithubPages = window.location.hostname.includes('github.io');
        // Always use hash-based routing for GitHub Pages and local development
        return isGithubPages 
            ? 'https://1Luckyle.github.io/phmc-forms/#/auth/gta/callback'
            : `${window.location.origin}/phmc-forms/#/auth/gta/callback`;
    });
    const [code, setCode] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [response, setResponse] = useState(null);
    const [error, setError] = useState(null);

    useEffect(() => {
        if (show) {
            console.info('[OAuth] Initializing OAuth modal');
            
            // Handle OAuth callback
            if (window.location.hash.includes('/auth/gta/callback')) {
                const urlParams = new URLSearchParams(window.location.hash.split('?')[1]);
                const codeFromHash = urlParams.get('code');
                const stateFromHash = urlParams.get('state');
                
                // Retrieve stored OAuth state
                const storedOAuthData = JSON.parse(sessionStorage.getItem('oauth-state') || '{}');
                
                console.debug('[OAuth] Validating OAuth state:', {
                    received: stateFromHash,
                    stored: storedOAuthData.state,
                    isValid: stateFromHash === storedOAuthData.state
                });
                
                if (codeFromHash && stateFromHash === storedOAuthData.state) {
                
                    console.debug('[OAuth] Valid OAuth state, restoring session');
                    
                    // Restore the OAuth modal state
                    setClientId(storedOAuthData.clientId || '');
                    setClientSecret(storedOAuthData.clientSecret || '');
                    setRedirectUri(storedOAuthData.redirectUri || redirectUri);
                    setCode(codeFromHash);
                    
                    // Store code for processing
                    sessionStorage.setItem('oauth-exchange-code', codeFromHash);
                    
                    // Clean up
                    sessionStorage.removeItem('oauth-state');
                    
                    // Redirect back to original location
                    window.location.replace(window.location.origin + storedOAuthData.returnPath);
                    return;
                } else {
                    console.error('[OAuth] Invalid or expired OAuth state');
                    setError({
                        error: 'Invalid OAuth State',
                        error_description: 'The OAuth flow was interrupted. Please try again.'
                    });
                }
            }
            
            // Check for code in URL params first (direct callback)
            const urlParams = new URLSearchParams(window.location.search);
            const codeFromUrl = urlParams.get('code');
            console.debug('[OAuth] Checking URL parameters for code');
            if (codeFromUrl) {
                setCode(codeFromUrl);
                // Clean up the URL
                const cleanUrl = window.location.href.split('?')[0];
                window.history.replaceState({}, document.title, cleanUrl);
                return;
            }
            
            // Fallback to session storage
            const storedCode = sessionStorage.getItem('oauth-exchange-code');
            if (storedCode) {
                setCode(storedCode);
                sessionStorage.removeItem('oauth-exchange-code');
            }
        }
    }, [show]);

    const handleGetCode = () => {
        console.info('[OAuth] Initiating authorization code request');
        
        // Generate a unique state for this OAuth request
        const oauthState = Math.random().toString(36).substring(2);
        
        // Store OAuth state and modal state
        const oauthData = {
            state: oauthState,
            returnPath: window.location.hash || '#/',
            clientId,
            clientSecret,
            redirectUri,
            timestamp: Date.now(),
            inProgress: true
        };
        
        // Store in sessionStorage
        sessionStorage.setItem('oauth-state', JSON.stringify(oauthData));
        
        console.debug('[OAuth] Stored OAuth state:', { oauthState, returnPath: oauthData.returnPath });
        
        // Include state parameter in OAuth request. Use the origin of tokenUrl or environment base to construct the authorization URL.
        let authBase;
        try {
            authBase = new URL(tokenUrl).origin;
        } catch (e) {
            authBase = process.env.REACT_APP_GTAWORLD_OAUTH_BASE_URL || 'https://ucp-fr.gta.world';
        }
        const authUrl = `${authBase}/oauth/authorize?response_type=code&client_id=${clientId}&redirect_uri=${encodeURIComponent(redirectUri)}&state=${oauthState}`;
        window.location.href = authUrl;
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        console.info('[OAuth] Starting token exchange submission');
        setIsLoading(true);
        setResponse(null);
        setError(null);

        const functionUrl = 'https://europe-west1-phmcfr-forms.cloudfunctions.net/exchangeAuthCodeForToken';
        console.debug('[OAuth] Using function URL:', functionUrl);
        
        try {
            console.debug('[OAuth] Sending token exchange request to:', functionUrl);
            const response = await fetch(functionUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ 
                    code, 
                    redirectUri,
                    clientId,
                    clientSecret,
                    tokenUrl
                }),
            });
            console.debug('[OAuth] Token exchange response status:', response.status);

            // Get the raw response text first
            const responseText = await response.text();
            console.debug('[OAuth] Raw response:', responseText);
            
            let data;
            try {
                data = JSON.parse(responseText);
            } catch (parseError) {
                console.error('[OAuth] Failed to parse response as JSON:', parseError);
                throw new Error(`Réponse JSON invalide du serveur. Reçue : ${responseText.substring(0, 100)}...`);
            }

            if (response.ok) {
                console.info('[OAuth] Token exchange successful');
                console.debug('[OAuth] Received user data:', { username: data.user?.username });
                setResponse(data.token);
                if (data.user) {
                    onUserDataReceived(data.user);
                    showNotification(`Échange de jeton OAuth réussi ! Bienvenue ${data.user.username}`, 'check-circle');
                }
                sendAdminActionWebhook(
                    adminUserEmail,
                    'Échange de jetons OAuth réussi',
                    `Succès : jeton et données utilisateur reçus`,
                    'Outils de développement'
                );
            } else {
                const errorData = data;
                setError(errorData);
                showNotification(`Échec de l'échange de jeton OAuth : ${errorData.error || response.statusText}`, 'error');
                sendAdminActionWebhook(
                    adminUserEmail,
                    'Échec de l\'échange de jeton OAuth',
                    `Erreur : ${JSON.stringify(errorData, null, 2)}`,
                    'Outils de développement'
                );
                Sentry.captureMessage(`OAuth Token Exchange failed: ${functionUrl}`, {
                    level: 'error',
                    extra: {
                        redirectUri,
                        response: errorData,
                        status: response.status,
                    }
                });
            }
        } catch (err) {
            console.error('Network error during OAuth Token Exchange:', err);
            setError({ error: 'Network Error', error_description: err.message });
            showNotification(`Erreur réseau : ${err.message}`, 'error');
            sendAdminActionWebhook(
                adminUserEmail,
                'Erreur réseau lors de l\'échange de jeton OAuth',
                `Erreur réseau : ${err.message}`,
                'Outils de développement'
            );
            Sentry.captureException(err, {
                extra: {
                    context: 'Erreur réseau lors de l\'échange de jeton OAuth',
                    functionUrl,
                    redirectUri,
                }
            });
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <Modal show={show} onHide={onHide} size="lg" centered>
            <Modal.Header closeButton>
                <Modal.Title>Échange de jeton OAuth</Modal.Title>
            </Modal.Header>
            <Modal.Body>
                <Form onSubmit={handleSubmit}>
                    <Form.Group className="mb-3">
                        <Form.Label>URL du point de terminaison du jeton</Form.Label>
                        <Form.Control
                            type="url"
                            value={tokenUrl}
                            onChange={(e) => setTokenUrl(e.target.value)}
                            placeholder="e.g., https://ucp-fr.gta.world/oauth/token"
                            required
                        />
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>ID client</Form.Label>
                        <Form.Control
                            type="text"
                            value={clientId}
                            onChange={(e) => setClientId(e.target.value)}
                            placeholder="Votre ID client OAuth"
                            required
                        />
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>Secret client</Form.Label>
                        <Form.Control
                            type="password"
                            value={clientSecret}
                            onChange={(e) => setClientSecret(e.target.value)}
                            placeholder="Votre secret client OAuth"
                            required
                        />
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>URL de redirection</Form.Label>
                        <Form.Control
                            type="url"
                            value={redirectUri}
                            onChange={(e) => setRedirectUri(e.target.value)}
                            placeholder="Votre URL de redirection enregistrée"
                            required
                        />
                    </Form.Group>
                    <Form.Group className="mb-3">
                        <Form.Label>Code d'autorisation</Form.Label>
                        <div className="d-flex">
                            <Form.Control
                                type="text"
                                value={code}
                                onChange={(e) => setCode(e.target.value)}
                                placeholder="Cliquez sur le bouton pour obtenir le code ->"
                                required
                            />
                            <Button variant="outline-secondary" onClick={handleGetCode} className="ms-2">Obtenir le code</Button>
                        </div>
                    </Form.Group>

                    {error && (
                        <Alert variant="danger">
                            <strong>Erreur :</strong> {error.error || 'Erreur inconnue'}
                            {error.error_description && `: ${error.error_description}`}
                            {error.message && `: ${error.message}`}
                            <pre className="mt-2">{JSON.stringify(error, null, 2)}</pre>
                        </Alert>
                    )}

                    {response && (
                        <Alert variant="success">
                            <strong>Succès !</strong> Token reçu.
                            <pre className="mt-2">{JSON.stringify(response, null, 2)}</pre>
                        </Alert>
                    )}

                    <Button variant="primary" type="submit" disabled={isLoading}>
                        {isLoading ? <Spinner as="span" animation="border" size="sm" role="status" aria-hidden="true" /> : <i className="fas fa-paper-plane me-2"></i>}
                        {isLoading ? 'Échange du code...' : 'Échanger le code contre un token'}
                    </Button>
                </Form>
            </Modal.Body>
        </Modal>
    );
};

export default OAuthTokenExchangeModal;